const items = $input.all();

const seen = new Set();
const chips = [];

for (const i of items) {
  const sid = String(i.json.sentrix_id);
  if (seen.has(sid)) continue;
  seen.add(sid);
  chips.push({
    sentrix_id: sid,
    scan_ref: String(i.json.scan_ref),
    chiptype_ref: String(i.json.chiptype_ref),
    idat_count: Number(i.json.idat_count),
    gtc_path_count: Number(i.json.gtc_path_count),
  });
}

if (chips.length === 0) {
  return [{ json: { status: 'nothing_to_process', message: 'İşlenecek çip bulunamadı' } }];
}

return [{ json: { status: 'process_batch', chip_count: chips.length, chips } }];

